const stage=document.querySelector('#stage');
const enemySprite=document.createElement('img');enemySprite.className='enemy-sprite';enemySprite.alt='混乱史莱姆';enemySprite.src='../../enemies/enemy_chaos_slime_etching_b01.png';stage.insertBefore(enemySprite,document.querySelector('.enemy-info'));
const heroSprite=document.createElement('img');heroSprite.className='hero-sprite';heroSprite.alt='学者';heroSprite.src='../../portraits/portrait_scholar_etching_b01.png';stage.insertBefore(heroSprite,document.querySelector('.player-info'));
const structural=['cover','page_edges','page_left','page_right','spine','binding','fold','ribbon'];const layerRoot=document.createElement('div');layerRoot.className='journal-layers';layerRoot.setAttribute('aria-hidden','true');structural.forEach(id=>{const i=document.createElement('img');i.src='../../journal/journal_'+id+'_a01.svg';i.className='journal-export';layerRoot.append(i)});document.querySelector('.journal').prepend(layerRoot);
const controls=document.createElement('div');controls.className='layer-controls';controls.innerHTML='<a href="../../batches/foundation-a01/">资源审阅</a><button id="toggle-sprites">隐藏立绘</button><label>敌人 <select id="enemy-select"><option value="chaos_slime">混乱史莱姆</option><option value="training_dummy">训练假人</option><option value="goblin">哥林布</option></select></label>';document.querySelector('.preview-controls').append(controls);
let spriteVisible=true;document.querySelector('#toggle-sprites').onclick=e=>{spriteVisible=!spriteVisible;enemySprite.hidden=heroSprite.hidden=!spriteVisible;e.target.textContent=spriteVisible?'隐藏立绘':'显示立绘'};
document.querySelector('#enemy-select').onchange=e=>{window.preview.setMode('normal');const data={chaos_slime:['混乱史莱姆',35,10,6],training_dummy:['训练假人',30,10,6],goblin:['哥林布',38,9,8]}[e.target.value];enemySprite.src='../../enemies/enemy_'+e.target.value+'_etching_b01.png';enemySprite.alt=data[0];document.querySelector('.enemy-heading h1').textContent=data[0];document.querySelector('.hp b').innerHTML=data[1]+' <small>/ '+data[1]+'</small>';document.querySelector('.intent strong').textContent=data[3];const meter=document.querySelector('#meter');meter.innerHTML=Array.from({length:data[2]},(_,i)=>'<span class="segment '+(i===0?'lit':'')+'"></span>').join('');meter.style.gridTemplateColumns='repeat('+data[2]+',1fr)';meter.setAttribute('aria-valuemax',data[2]);meter.setAttribute('aria-valuenow','1');document.querySelector('#action-value').innerHTML='1 <small>/ '+data[2]+'</small>';document.querySelector('#remaining').textContent='距行动 '+(data[2]-1)+' 点';document.querySelector('#stage').classList.remove('danger');document.querySelector('#danger').disabled=e.target.value!=='chaos_slime';document.querySelector('#normal').disabled=e.target.value!=='chaos_slime';document.querySelector('.card.face').disabled=e.target.value!=='chaos_slime';document.querySelector('#show-detail').disabled=e.target.value!=='chaos_slime';document.querySelector('#detail').hidden=true;document.querySelector('#stage').classList.remove('detail-open');};

